function getAirportInfo(code) {
  if (!code) return { code: '', name: 'Unknown', city: 'Unknown', country: 'Unknown', lat: 0, lon: 0, flag: '✈️' };
  const upper = code.toUpperCase().trim();
  if (AIRPORTS_DATA[upper]) {
    return { code: upper, ...AIRPORTS_DATA[upper] };
  }
  return {
    code: upper,
    name: `${upper} Airport`,
    city: upper,
    country: 'International',
    lat: 0,
    lon: 0,
    flag: '✈️'
  };
}

if (typeof window !== 'undefined') {
  window.AIRPORTS_DATA = AIRPORTS_DATA;
  window.getAirportInfo = getAirportInfo;
}
